"use client";

import type { Breakpoint } from "@audio-ui/core/envelope";
import { useCallback, useMemo } from "react";
import { IconPlaceholder } from "@/components/icon-placeholder";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { AutomationEnvelope } from "@/components/audio-ui/automation-envelope";
import {
  type ArrangementTrack,
  type AutomatedParameter,
  flatAutomation,
  type Mix,
  panPosition,
  volumeGain,
  volumeValue,
} from "@/lib/arrangement";

/** A gain as the decibels it plays at. */
function formatGain(gain: number) {
  if (gain <= 0) {
    return "-inf dB";
  }
  const db = 20 * Math.log10(gain);
  return `${db > 0 ? "+" : ""}${db.toFixed(1)} dB`;
}

/** What each parameter a track automates is called, how its envelope's values read, and where it stands in the mix. */
const PARAMETERS: Record<
  AutomatedParameter,
  { format: (y: number) => string; label: string; ofMix: (mix: Mix) => number }
> = {
  pan: {
    format: (y) => {
      const pan = Math.round(panPosition(y) * 100);
      if (pan === 0) {
        return "C";
      }
      return `${pan < 0 ? "L" : "R"}${Math.abs(pan)}`;
    },
    label: "Pan",
    ofMix: (mix) => (mix.pan + 1) / 2,
  },
  volume: {
    format: (y) => formatGain(volumeGain(y)),
    label: "Volume",
    ofMix: (mix) => volumeValue(mix.gain),
  },
};

/** The parameters a track automates, in the chooser's order. */
export const AUTOMATED_PARAMETERS = ["volume", "pan"] as const;

const PARAMETER_ITEMS = AUTOMATED_PARAMETERS.map((value) => ({
  label: PARAMETERS[value].label,
  value,
}));

/** In a track's header: which parameter its lane shows, a dot on the ones automated, and a button that clears that envelope. */
function TrackAutomationChooser({
  onClear,
  onParameterChange,
  parameter,
  track,
}: {
  onClear: (trackId: string, parameter: AutomatedParameter) => void;
  onParameterChange: (trackId: string, parameter: AutomatedParameter) => void;
  parameter: AutomatedParameter;
  track: ArrangementTrack;
}) {
  const { automation, id: trackId, name } = track;
  const change = useCallback(
    (next: string | null) =>
      onParameterChange(trackId, next === "pan" ? "pan" : "volume"),
    [onParameterChange, trackId]
  );
  const clear = useCallback(
    () => onClear(trackId, parameter),
    [onClear, parameter, trackId]
  );
  const { label } = PARAMETERS[parameter];
  return (
    <div
      className="flex h-7 items-center gap-1 pe-1"
      data-slot="track-automation-chooser"
    >
      <Select items={PARAMETER_ITEMS} onValueChange={change} value={parameter}>
        <SelectTrigger
          aria-label={`${name} automation`}
          className="min-w-0 flex-1"
          size="sm"
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          <SelectGroup>
            {PARAMETER_ITEMS.map((item) => (
              <SelectItem key={item.value} value={item.value}>
                {item.label}
                {automation?.[item.value] ? (
                  <span
                    aria-label="automated"
                    className="size-1.5 self-center rounded-full bg-primary"
                    role="img"
                  />
                ) : null}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
      <Button
        aria-label={`Clear the ${label.toLowerCase()} envelope of ${name}`}
        disabled={!automation?.[parameter]}
        onClick={clear}
        size="icon-xs"
        variant="ghost"
      >
        <IconPlaceholder
          hugeicons="Delete02Icon"
          lucide="Trash2Icon"
          phosphor="TrashIcon"
          remixicon="RiDeleteBinLine"
          tabler="IconTrash"
        />
      </Button>
    </div>
  );
}

/**
 * A track's envelope for one parameter, over its lane. Until the track has
 * one, the line stands flat at the mix's value, faint, and the first edit
 * draws it; a parameter moved by hand since (`overridden`) is greyed, as its
 * mix is what plays.
 */
function TrackAutomation({
  describe,
  duration,
  mix,
  onChange,
  onCommit,
  overridden = [],
  parameter,
  snapStep,
  track,
}: {
  /** A time of the arrangement in words, such as "Bar 3, beat 2", for each point's value text. */
  describe: (seconds: number) => string;
  duration: number;
  mix: Mix;
  onChange: (
    trackId: string,
    parameter: AutomatedParameter,
    points: readonly Breakpoint[]
  ) => void;
  onCommit: () => void;
  /** The track's parameters moved by hand since they were automated. */
  overridden?: readonly AutomatedParameter[];
  parameter: AutomatedParameter;
  /** The grid a point snaps to in time, in the arrangement's units. 0 is free. */
  snapStep: number;
  track: ArrangementTrack;
}) {
  const { id: trackId, name: trackName } = track;
  const points = track.automation?.[parameter];
  const { format, label, ofMix } = PARAMETERS[parameter];
  const standing = ofMix(mix);
  const value = useMemo(
    () => (points ? [...points] : flatAutomation(standing)),
    [points, standing]
  );
  const change = useCallback(
    (next: Breakpoint[]) => onChange(trackId, parameter, next),
    [onChange, parameter, trackId]
  );
  const formatValue = useCallback(
    (point: { x: number; y: number }) =>
      `${describe(point.x * duration)}, ${format(point.y)}`,
    [describe, duration, format]
  );
  return (
    <AutomationEnvelope
      aria-label={`${trackName} ${label.toLowerCase()} automation`}
      className={cn(
        !points && "opacity-50",
        overridden.includes(parameter) && "opacity-50 grayscale"
      )}
      duration={duration}
      formatValue={formatValue}
      onValueChange={change}
      onValueCommitted={onCommit}
      snap={{ x: snapStep / duration, y: 0 }}
      value={value}
    />
  );
}

export { TrackAutomation, TrackAutomationChooser };

"use client";

import type { Breakpoint } from "@audio-ui/core/envelope";
import { useCallback, useState } from "react";
import { AUTOMATED_PARAMETERS } from "@/components/audio-ui/track-automation";
import type {
  ArrangementTrack,
  AutomatedParameter,
  Mix,
} from "@/lib/arrangement";
import type { ArrangementCommand } from "@/lib/arrangement-state";

export interface UseTrackAutomationOptions {
  /** The arrangement's commands, as `useArrangement` returns them. */
  dispatch: (command: ArrangementCommand) => unknown;
  /** The tracks whose automation a change by hand overrides. */
  tracks: readonly ArrangementTrack[];
}

/**
 * The automation of an arrangement's tracks, as a DAW's automation mode has
 * it. `automating` shows each track's envelope over its lane and the chooser
 * of its parameter in its header (`TrackAutomation`, `TrackAutomationChooser`).
 * A gain or a pan moved by hand through `changeMix` overrides the envelope:
 * `overridden` lists, by track, what plays its mix instead (give it to the
 * engine), until `reenable`, or until `edit` draws that envelope again.
 * `clear` takes an envelope away, as one step of undo.
 */
export function useTrackAutomation({
  dispatch,
  tracks,
}: UseTrackAutomationOptions) {
  const [automating, setAutomating] = useState(false);
  const [shown, setShown] = useState<Record<string, AutomatedParameter>>({});
  const [overridden, setOverridden] = useState<
    Record<string, AutomatedParameter[]>
  >({});
  /** The parameter a track's lane shows: its volume until another is chosen. */
  const parameterOf = useCallback(
    (trackId: string): AutomatedParameter => shown[trackId] ?? "volume",
    [shown]
  );
  const show = useCallback(
    (trackId: string, parameter: AutomatedParameter) =>
      setShown((all) => ({ ...all, [trackId]: parameter })),
    []
  );
  const toggle = useCallback(() => setAutomating((on) => !on), []);
  /** A track's mix changed by hand: a fader's drag is a burst, a switch a step of its own, and an automated gain or pan stops following its envelope. */
  const changeMix = useCallback(
    (trackId: string, patch: Partial<Mix>) => {
      const automation = tracks.find(
        (track) => track.id === trackId
      )?.automation;
      const moved = AUTOMATED_PARAMETERS.filter(
        (parameter) =>
          automation?.[parameter] &&
          (parameter === "volume" ? "gain" : "pan") in patch
      );
      if (moved.length > 0) {
        setOverridden((all) => ({
          ...all,
          [trackId]: [...new Set([...(all[trackId] ?? []), ...moved])],
        }));
      }
      const { color, ...rest } = patch;
      if (color !== undefined) {
        dispatch({ color, id: trackId, type: "set-track-color" });
      }
      if (Object.keys(rest).length > 0) {
        dispatch({
          id: trackId,
          patch: rest,
          type: "gain" in rest || "pan" in rest ? "change-mix" : "set-mix",
        });
      }
    },
    [dispatch, tracks]
  );
  /** Draws a track's envelope: drawn, it plays again. */
  const edit = useCallback(
    (
      trackId: string,
      parameter: AutomatedParameter,
      points: readonly Breakpoint[]
    ) => {
      setOverridden((all) =>
        all[trackId]?.includes(parameter)
          ? {
              ...all,
              [trackId]: all[trackId].filter((item) => item !== parameter),
            }
          : all
      );
      dispatch({ parameter, points, trackId, type: "change-automation" });
    },
    [dispatch]
  );
  const clear = useCallback(
    (trackId: string, parameter: AutomatedParameter) => {
      dispatch({ parameter, points: null, trackId, type: "change-automation" });
      dispatch({ type: "settle-clip-edit" });
    },
    [dispatch]
  );
  const reenable = useCallback(() => setOverridden({}), []);
  return {
    /** Whether a change by hand overrides any envelope: what a "Re-enable automation" button waits for. */
    anyOverridden: Object.values(overridden).some(
      (parameters) => parameters.length > 0
    ),
    automating,
    changeMix,
    clear,
    edit,
    overridden,
    parameterOf,
    reenable,
    setAutomating,
    show,
    toggle,
  };
}
